from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final[Path] = Path("notes")


def first_readable(names: list[str]) -> str:
    """Return the text of the first readable file in NOTES_DIR named in names.

    Names are untrusted. Only regular files inside NOTES_DIR (relative to the
    working directory) are read. A name that is missing, unreadable, a
    directory, or that resolves outside NOTES_DIR is skipped. Returns "" when
    no name yields a readable file.
    """
    base = NOTES_DIR.resolve()
    for name in names:
        if not name or "\x00" in name:
            continue
        try:
            candidate = (base / name).resolve()
        except (OSError, RuntimeError, ValueError):
            continue
        if not candidate.is_relative_to(base):
            continue
        if not candidate.is_file():
            continue
        try:
            return candidate.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
    return ""


@pytest.fixture
def notes(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    d = tmp_path / "notes"
    d.mkdir()
    (tmp_path / "secret.txt").write_text("SECRET", encoding="utf-8")
    return d


def test_empty_list_returns_empty(notes: Path) -> None:
    assert first_readable([]) == ""


def test_returns_first_readable(notes: Path) -> None:
    (notes / "a.txt").write_text("A", encoding="utf-8")
    (notes / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["a.txt", "b.txt"]) == "A"


def test_skips_missing_file(notes: Path) -> None:
    (notes / "b.txt").write_text("B", encoding="utf-8")
    assert first_readable(["nope.txt", "b.txt"]) == "B"


def test_none_readable_returns_empty(notes: Path) -> None:
    assert first_readable(["x.txt", "y.txt"]) == ""


def test_directory_is_not_readable(notes: Path) -> None:
    (notes / "dir").mkdir()
    assert first_readable(["dir"]) == ""


@pytest.mark.parametrize(
    "name",
    [
        "../secret.txt",
        "sub/../../secret.txt",
        "..\\secret.txt",
        "..",
        ".",
        "",
    ],
)
def test_traversal_names_do_not_escape(notes: Path, name: str) -> None:
    assert first_readable([name]) == ""


def test_absolute_path_does_not_escape(notes: Path, tmp_path: Path) -> None:
    secret = str(tmp_path / "secret.txt")
    assert first_readable([secret]) == ""


def test_traversal_then_valid_name(notes: Path) -> None:
    (notes / "ok.txt").write_text("OK", encoding="utf-8")
    assert first_readable(["../secret.txt", "ok.txt"]) == "OK"


def test_symlink_pointing_outside_is_not_followed(notes: Path, tmp_path: Path) -> None:
    try:
        (notes / "link.txt").symlink_to(tmp_path / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported on this platform")
    assert first_readable(["link.txt"]) == ""


def test_nul_byte_name_returns_empty(notes: Path) -> None:
    assert first_readable(["a\x00.txt"]) == ""
